-- Audit triggers and the attach list for every table (hand-written; Prisma cannot express triggers).
--
-- This file is appended to the generated table definitions when the baseline migration is made
-- (npm run db:baseline). Keep it as the single source of truth: a table that needs the audit columns
-- gets a SELECT audit_attach(...) line at the bottom, and a later migration repeats just that line.
--
--   Adds the database triggers that stamp createdAt/updatedAt/createdById/updatedById and write
--   "ActivityLog" rows. The columns and the "ActivityLog" table come from the generated DDL.
--
-- Who is acting is passed per transaction by the application:
--   SELECT set_config('app.audit', '{"actorId":"...","actorName":"...","actorRole":"...",
--                                    "source":"WEB","requestId":"...","ip":"...","userAgent":"..."}', true);
-- (see lib/audit/run.ts). Writes without it are still recorded, with no actor and source SYSTEM.

-- ---------------------------------------------------------------------------
-- Trigger functions
-- ---------------------------------------------------------------------------

-- The acting user for this transaction. A missing or malformed value must never block a write,
-- so it falls back to "no actor".
CREATE OR REPLACE FUNCTION audit_context() RETURNS jsonb
LANGUAGE plpgsql STABLE AS $fn$
DECLARE
  raw text := current_setting('app.audit', true);
BEGIN
  IF raw IS NULL OR raw = '' THEN
    RETURN '{}'::jsonb;
  END IF;
  RETURN raw::jsonb;
EXCEPTION WHEN others THEN
  RETURN '{}'::jsonb;
END
$fn$;

-- BEFORE INSERT OR UPDATE: keep the audit columns correct whatever the application sends.
-- Timestamps are written in UTC, like Prisma does, whatever the session time zone is.
CREATE OR REPLACE FUNCTION audit_stamp() RETURNS trigger
LANGUAGE plpgsql AS $fn$
DECLARE
  actor text := nullif(audit_context() ->> 'actorId', '');
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW."createdById" := actor;
  ELSE
    NEW."createdById" := OLD."createdById";
    NEW."createdAt" := OLD."createdAt";
  END IF;
  NEW."updatedById" := actor;
  NEW."updatedAt" := timezone('UTC', now());
  RETURN NEW;
END
$fn$;

-- AFTER INSERT OR UPDATE OR DELETE: one "ActivityLog" row per changed row, with field-level
-- before/after values.
--   TG_ARGV[0]  comma-separated columns to ignore (a change to only these writes no row)
--   TG_ARGV[1]  comma-separated columns whose values are replaced by "[redacted]"
CREATE OR REPLACE FUNCTION audit_log() RETURNS trigger
LANGUAGE plpgsql AS $fn$
DECLARE
  ctx    jsonb  := audit_context();
  skip   text[] := ARRAY['createdAt', 'updatedAt', 'createdById', 'updatedById']
                   || string_to_array(coalesce(TG_ARGV[0], ''), ',');
  redact text[] := string_to_array(coalesce(TG_ARGV[1], ''), ',');
  old_j  jsonb;
  new_j  jsonb;
  row_j  jsonb;
  diff   jsonb;
  act    text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    old_j := '{}'::jsonb;
    new_j := to_jsonb(NEW);
    row_j := new_j;
  ELSIF TG_OP = 'UPDATE' THEN
    old_j := to_jsonb(OLD);
    new_j := to_jsonb(NEW);
    row_j := new_j;
  ELSE
    old_j := to_jsonb(OLD);
    new_j := '{}'::jsonb;
    row_j := old_j;
  END IF;

  SELECT coalesce(jsonb_agg(
           jsonb_build_object(
             'field', k.key,
             'from', CASE WHEN k.key = ANY (redact)
                               AND (old_j -> k.key) IS NOT NULL
                               AND jsonb_typeof(old_j -> k.key) <> 'null'
                          THEN to_jsonb('[redacted]'::text)
                          ELSE old_j -> k.key END,
             'to',   CASE WHEN k.key = ANY (redact)
                               AND (new_j -> k.key) IS NOT NULL
                               AND jsonb_typeof(new_j -> k.key) <> 'null'
                          THEN to_jsonb('[redacted]'::text)
                          ELSE new_j -> k.key END
           ) ORDER BY k.key), '[]'::jsonb)
    INTO diff
    FROM (SELECT DISTINCT jsonb_object_keys(old_j || new_j) AS key) AS k
   WHERE NOT (k.key = ANY (skip))
     AND (old_j -> k.key) IS DISTINCT FROM (new_j -> k.key);

  IF jsonb_array_length(diff) = 0 THEN
    RETURN NULL;
  END IF;

  act := CASE TG_OP WHEN 'INSERT' THEN 'CREATE' WHEN 'DELETE' THEN 'DELETE' ELSE 'UPDATE' END;
  IF TG_OP = 'UPDATE' THEN
    IF jsonb_typeof(old_j -> 'deletedAt') = 'null' AND jsonb_typeof(new_j -> 'deletedAt') <> 'null' THEN
      act := 'SOFT_DELETE';
    ELSIF jsonb_typeof(old_j -> 'deletedAt') <> 'null' AND jsonb_typeof(new_j -> 'deletedAt') = 'null' THEN
      act := 'RESTORE';
    END IF;
  END IF;

  INSERT INTO "ActivityLog" (
    "id", "createdAt", "entityType", "entityId", "shopId", "action", "changes",
    "actorId", "actorName", "actorRole", "onBehalfOfId", "impersonationId",
    "source", "requestId", "ip", "userAgent"
  ) VALUES (
    gen_random_uuid()::text,
    timezone('UTC', now()),
    TG_TABLE_NAME,
    row_j ->> 'id',
    coalesce(row_j ->> 'shopId', CASE WHEN TG_TABLE_NAME = 'Shop' THEN row_j ->> 'id' END),
    act,
    diff,
    nullif(ctx ->> 'actorId', ''),
    nullif(ctx ->> 'actorName', ''),
    nullif(ctx ->> 'actorRole', ''),
    nullif(ctx ->> 'onBehalfOfId', ''),
    nullif(ctx ->> 'impersonationId', ''),
    coalesce(nullif(ctx ->> 'source', ''), 'SYSTEM'),
    nullif(ctx ->> 'requestId', ''),
    nullif(ctx ->> 'ip', ''),
    nullif(ctx ->> 'userAgent', '')
  );
  RETURN NULL;
END
$fn$;

-- "ActivityLog" is append-only. A retention or erasure job can lift the guard for one transaction:
--   SELECT set_config('app.audit_maintenance', 'on', true);
CREATE OR REPLACE FUNCTION activity_log_guard() RETURNS trigger
LANGUAGE plpgsql AS $fn$
BEGIN
  IF coalesce(current_setting('app.audit_maintenance', true), '') = 'on' THEN
    IF TG_OP = 'UPDATE' THEN
      RETURN NEW;
    ELSIF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NULL;
  END IF;
  RAISE EXCEPTION 'ActivityLog is append-only (% blocked)', TG_OP USING ERRCODE = '55000';
END
$fn$;

CREATE TRIGGER activity_log_guard
BEFORE UPDATE OR DELETE ON "ActivityLog"
FOR EACH ROW EXECUTE FUNCTION activity_log_guard();

CREATE TRIGGER activity_log_guard_truncate
BEFORE TRUNCATE ON "ActivityLog"
FOR EACH STATEMENT EXECUTE FUNCTION activity_log_guard();

-- Attach the audit triggers to a table (re-runnable).
--   with_log = false  stamps the audit columns only (no ActivityLog rows)
CREATE OR REPLACE FUNCTION audit_attach(
  tbl        text,
  log_ignore text    DEFAULT '',
  log_redact text    DEFAULT '',
  with_log   boolean DEFAULT true
) RETURNS void
LANGUAGE plpgsql AS $fn$
BEGIN
  EXECUTE format('DROP TRIGGER IF EXISTS audit_stamp ON %I', tbl);
  EXECUTE format(
    'CREATE TRIGGER audit_stamp BEFORE INSERT OR UPDATE ON %I
       FOR EACH ROW EXECUTE FUNCTION audit_stamp()', tbl);
  EXECUTE format('DROP TRIGGER IF EXISTS audit_log ON %I', tbl);
  IF with_log THEN
    EXECUTE format(
      'CREATE TRIGGER audit_log AFTER INSERT OR UPDATE OR DELETE ON %I
         FOR EACH ROW EXECUTE FUNCTION audit_log(%L, %L)', tbl, log_ignore, log_redact);
  END IF;
END
$fn$;

-- ---------------------------------------------------------------------------
-- Attach to every table
--   audit_attach(table, columns whose change alone writes no log row, columns shown as [redacted], with_log)
-- ---------------------------------------------------------------------------
SELECT audit_attach('User', 'lastLoginAt', 'password');
SELECT audit_attach('Shop');
SELECT audit_attach('Business');
SELECT audit_attach('Category');
SELECT audit_attach('CatalogItem');
SELECT audit_attach('CatalogSuggestion');
SELECT audit_attach('Product');
SELECT audit_attach('Account', 'expires_at', 'refresh_token,access_token,id_token');
SELECT audit_attach('PasswordResetToken', '', 'token');
SELECT audit_attach('LoginSession', 'lastActiveAt');
SELECT audit_attach('AccessRole');
SELECT audit_attach('AccessAssignment');
SELECT audit_attach('AccessInvite', '', 'tokenHash');
SELECT audit_attach('ImpersonationSession');
SELECT audit_attach('Plan');
SELECT audit_attach('Subscription');
SELECT audit_attach('ContactMessage', '', 'message');
-- Stamp only (no log rows): secrets, counters and notifications whose event is already logged.
SELECT audit_attach('Notification', '', '', false);
SELECT audit_attach('RateLimit', '', '', false);
SELECT audit_attach('Session', '', '', false);
SELECT audit_attach('VerificationToken', '', '', false);
